style.css:
@-moz-document domain("roblox.com") {
/* Main Background */
    body, 
    .dark-theme, 
    .light-theme, 
    .content {
        background-image: url(https://media.giphy.com/media/v1.Y2lkPTc5MGI3NjExbnY5aDJ2YmtxYXJzYWJsdHF5ZHdtNTB3YmU3cHlycmwwOTQ0NGVmdCZlcD12MV9naWZzX3NlYXJjaCZjdD1n/93mS3A87wfmOySC29W/giphy.gif) !important;
        background-size: cover !important;
        background-attachment: fixed !important;
        background-position: center !important;
    }

    /* Makes container boxes semi-transparent so you can see the cat */
    .section-content, 
    .container-main, 
    .game-card-container,
    #header {
        background: rgba(255, 255, 255, 0.15) !important;
        backdrop-filter: blur(5px);
    }
}
